style.css:
/* General body styling for a spooky vibe */
body {
    background-color: #2a2a2a; /* Dark grayish background */
    color: #f5f5f5; /* Soft white text */
    font-family: 'Creepster', cursive, sans-serif; /* A spooky font */
    margin: 0;
    padding: 0;
    display: flex;
    justify-content: center;
    align-items: center;
    height: 100vh;
    overflow: hidden;
}
